#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int parent;
    int rank;
    ll diff; /* value[node] - value[parent] */
} DSU;

static int find_root(DSU *dsu, int x) {
    if (dsu[x].parent == x) return x;
    int p = dsu[x].parent;
    int r = find_root(dsu, p);
    dsu[x].diff += dsu[p].diff; /* value[x] - value[root] */
    dsu[x].parent = r;
    return r;
}

static ll weight_to_root(DSU *dsu, int x) {
    find_root(dsu, x);
    return dsu[x].diff; /* value[x] - value[root] */
}

/* impose: value[y] - value[x] = w */
static void unite(DSU *dsu, int x, int y, ll w) {
    int rx = find_root(dsu, x);
    int ry = find_root(dsu, y);
    ll wx = weight_to_root(dsu, x);
    ll wy = weight_to_root(dsu, y);

    if (rx == ry) return;

    /* Need to set parent relation between roots */
    /* Since:
       value[y] - value[x] = w
       (value[ry] + wy) - (value[rx] + wx) = w
       value[ry] - value[rx] = w + wx - wy
    */
    ll d = w + wx - wy; /* value[ry] - value[rx] */

    if (dsu[rx].rank < dsu[ry].rank) {
        /* attach rx under ry
           need diff[rx] = value[rx] - value[ry] = -d
        */
        dsu[rx].parent = ry;
        dsu[rx].diff = -d;
    } else {
        /* attach ry under rx
           need diff[ry] = value[ry] - value[rx] = d
        */
        dsu[ry].parent = rx;
        dsu[ry].diff = d;
        if (dsu[rx].rank == dsu[ry].rank) dsu[rx].rank++;
    }
}

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;

    DSU *dsu = (DSU *)malloc(sizeof(DSU) * n);
    for (int i = 0; i < n; i++) {
        dsu[i].parent = i;
        dsu[i].rank = 0;
        dsu[i].diff = 0;
    }

    for (int i = 0; i < q; i++) {
        char op[16];
        scanf("%s", op);

        if (op[0] == 'r') {
            int x, y;
            ll z;
            scanf("%d %d %lld", &x, &y, &z);
            unite(dsu, x, y, z);
        } else { /* diff */
            int x, y;
            scanf("%d %d", &x, &y);
            ll wx = weight_to_root(dsu, x);
            ll wy = weight_to_root(dsu, y);
            printf("%lld\n", wy - wx); /* value[y] - value[x] */
        }
    }

    free(dsu);
    return 0;
}

