struct DSU {
    vector<int> parent, rank;
    vector<long long> diff; // diff[i] = a_i - a_parent[i]

    DSU(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        diff.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x) {
            int orig_parent = parent[x];
            parent[x] = find(parent[x]);
            diff[x] += diff[orig_parent];
        }
        return parent[x];
    }

    long long get_diff(int x) {
        find(x);
        return diff[x];
    }

    // relate: a_y = a_x + z
    bool unite(int x, int y, long long z) {
        int rx = find(x), ry = find(y);
        if (rx == ry) {
            // Check consistency
            return (get_diff(y) - get_diff(x) == z);
        }
        // Attach rx under ry or vice versa
        // We want: a_y = a_x + z
        // diff[x] = a_x - a_rx, diff[y] = a_y - a_ry
        // We set parent[rx] = ry, then need:
        // a_rx = a_ry + (diff[y] - diff[x] - z)
        long long delta = get_diff(y) - get_diff(x) - z;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
            diff[rx] = -delta;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
            diff[ry] = delta;
        } else {
            parent[rx] = ry;
            diff[rx] = -delta;
            rank[ry]++;
        }
        return true;
    }
};

