#include <bits/stdc++.h>
using namespace std;

/*
Weighted Union-Find (Disjoint Set Union with potentials)

We maintain:
  parent[x] : parent of x
  sz[x]     : size of component rooted at x
  diffw[x]  : potential from x to parent[x]
             i.e. value(parent[x]) - value(x)

Then after path compression, diffw[x] becomes:
             value(root(x)) - value(x)

For relate(x, y, z):
  a_y - a_x = z

If rx = root(x), ry = root(y), and we know:
  weight(x) = value(root(x)) - value(x)
  weight(y) = value(root(y)) - value(y)

To merge ry under rx, we need diffw[ry] so that:
  value(rx) - value(ry) = z + weight(y) - weight(x)

This is the standard weighted DSU formula.
*/

struct WeightedDSU {
    vector<int> parent, sz;
    vector<long long> diffw; // value(parent) - value(node)

    WeightedDSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        diffw.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        parent[x] = find(parent[x]);
        diffw[x] += diffw[p];
        return parent[x];
    }

    long long weight(int x) {
        find(x);
        return diffw[x]; // value(root) - value(x)
    }

    bool unite(int x, int y, long long z) {
        // impose: a_y - a_x = z
        int rx = find(x), ry = find(y);
        long long wx = weight(x);
        long long wy = weight(y);

        if (rx == ry) return true;

        // Need value(rx) - value(ry)
        long long w = z + wy - wx;

        if (sz[rx] < sz[ry]) {
            // attach rx under ry instead
            swap(rx, ry);
            w = -w;
        }

        parent[ry] = rx;
        diffw[ry] = w; // value(rx) - value(ry)
        sz[rx] += sz[ry];
        return true;
    }

    long long diff(int x, int y) {
        // returns a_y - a_x
        // = (value(root)-value(x)) and (value(root)-value(y))
        // => a_y - a_x = weight(x) - weight(y)
        return weight(x) - weight(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;

    WeightedDSU dsu(n);

    while (q--) {
