        if (op == "relate") {
            int x, y;
            long long z;
            cin >> x >> y >> z;
            dsu.unite(x, y, z);
        } else if (op == "diff") {
            int x, y;
            cin >> x >> y;
            cout << dsu.diff(x, y) << '\n';
        }
    }

    return 0;
}

import java.io.*;
