public class Main {
    static int[] parent;
    static long[] diff; // diff[i] = a_i - a_root(i)

    static int find(int x) {
        if (parent[x] != x) {
            int origParent = parent[x];
            parent[x] = find(parent[x]);
            diff[x] += diff[origParent];
        }
        return parent[x];
    }

    static boolean relate(int x, int y, long z) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) {
            // Check consistency: a_y - a_x == z ?
            return diff[y] - diff[x] == z;
        }
        // Merge ry under rx
        parent[ry] = rx;
        // diff[ry] should satisfy: diff[y] - (diff[x] + diff[ry]) = z
        // so diff[ry] = diff[y] - diff[x] - z
        diff[ry] = diff[y] - diff[x] - z;
        return true;
    }

    static Long diffQuery(int x, int y) {
        if (find(x) != find(y)) {
            return null;
        }
        return diff[y] - diff[x];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            String[] parts = line.split(" ");
            if (parts.length == 0) continue;
            String type = parts[0];

            if (type.equals("relate")) {
                int x = Integer.parseInt(parts[1]);
                int y = Integer.parseInt(parts[2]);
                long z = Long.parseLong(parts[3]);

                int n = Math.max(x, y) + 1;
                if (parent == null) {
                    parent = new int[n];
                    diff = new long[n];
                    for (int i = 0; i < n; i++) {
                        parent[i] = i;
                        diff[i] = 0;
                    }
                } else if (n > parent.length) {
                    int oldLen = parent.length;
                    parent = Arrays.copyOf(parent, n);
                    diff = Arrays.copyOf(diff, n);
                    for (int i = oldLen; i < n; i++) {
                        parent[i] = i;
                        diff[i] = 0;
                    }
                }
                relate(x, y, z);

            } else if (type.equals("diff")) {
                int x = Integer.parseInt(parts[1]);
                int y = Integer.parseInt(parts[2]);
                Long result = diffQuery(x, y);
                if (result == null) {
                    out.append("?").append("\n");
                } else {
                    out.append(result).append("\n");
                }
            }
        }
        System.out.print(out);
    }
}

