import java.io.*;
import java.util.*;

public class Main {
    // Weighted Union-Find:
    // weight[x] = potential(x) - potential(parent[x])
    // For this problem, potential(i) = a_i
    static class WeightedDSU {
        int[] parent;
        int[] size;
        long[] weight;

        WeightedDSU(int n) {
            parent = new int[n];
            size = new int[n];
            weight = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
                weight[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] == x) return x;
            int p = parent[x];
            int r = find(p);
            weight[x] += weight[p];
            return parent[x] = r;
        }

        long potential(int x) {
            find(x);
            return weight[x];
        }

        // impose: potential(y) - potential(x) = w
        void unite(int x, int y, long w) {
            long px = potential(x);
            long py = potential(y);
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;

            // Need: (potential(y) - potential(x)) = w
            // Let new relation between roots be set accordingly.
            // weight[root] = potential(root) - potential(newParent)
            long diff = w + px - py;

            if (size[rx] < size[ry]) {
                parent[rx] = ry;
                weight[rx] = -diff;
                size[ry] += size[rx];
            } else {
                parent[ry] = rx;
                weight[ry] = diff;
                size[rx] += size[ry];
            }
        }

        long diff(int x, int y) {
            return potential(y) - potential(x);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        int q = fs.nextInt();

        WeightedDSU dsu = new WeightedDSU(n);
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String type = fs.next();
            if (type.equals("relate")) {
                int x = fs.nextInt();
                int y = fs.nextInt();
                long z = fs.nextLong();
                dsu.unite(x, y, z); // a_y - a_x = z
            } else if (type.equals("diff")) {
                int x = fs.nextInt();
                int y = fs.nextInt();
                out.append(dsu.diff(x, y)).append('\n'); // a_y - a_x
            }
        }

        System.out.print(out.toString());
    }
}
